        res.classList.remove('is-empty');
        var o = { price: f.aov.get(), cost: f.cost.get(), ship: f.ship.get(), pack: 0, ad: 0, ret: f.ret.get() / 100, feePct: f.feePct.get() / 100, feeFix: f.feeFix.get(), reg: vc.reg.get() === 'yes', incl: vc.incl.get() === 'yes' };
        var r = calc(o), cpa = r.profit; // the most you can pay for one order before you lose money
        var paid = r.paid; // ROAS is read on what the customer paid (what the pixel reports)
        var dead = cpa <= 0;
