  function offers(o) {
    // o: price, cost, shipCost (what you pay a carrier), custShip (customer pays shipping normally: true/false), disc, gift, reg, incl, feePct, feeFix
    var base = { price: o.price, cost: o.cost, ship: o.custShip ? 0 : o.shipCost, pack: 0, ad: 0, ret: 0, feePct: o.feePct, feeFix: o.feeFix, reg: o.reg, incl: o.incl };
    function with_(ch) { var x = {}; for (var k in base) x[k] = base[k]; for (var c in ch) x[c] = ch[c]; return calc(x).profit; }
    var b = with_({});
    var list = [
      { k: 'disc', profit: with_({ price: o.price * (1 - o.disc) }) },
      { k: 'free', profit: with_({ ship: o.shipCost }) },
      { k: 'gift', profit: with_({ cost: o.cost + o.gift }) },
      { k: 'b3', profit: with_({ price: o.price * 2, cost: o.cost * 3 }) }
    ];
    list.forEach(function (x) { x.need = x.profit > 0 ? b / x.profit - 1 : NaN; });
    return { base: b, list: list };
  }
  JT.offersCalc = offers;
